const username = $json.body.erp_username;
const password = $json.body.erp_password;

// Open ERP login page
await $page.goto(
  'https://meta-digitrading.lhike-erp.com/home',
  {
    waitUntil: 'networkidle2',
    timeout: 60000
  }
);

// Wait for login form
await $page.waitForSelector('input[name="txtusername"]', {
  timeout: 30000
});

// Fill credentials
await $page.type('input[name="txtusername"]', username, {
  delay: 50
});

await $page.type('input[name="txtpass"]', password, {
  delay: 50
});

// Submit login form
await Promise.all([
  $page.click('button[type="submit"]'),
  $page.waitForNavigation({
    waitUntil: 'networkidle2',
    timeout: 60000
  }).catch(() => null)
]);

// Check for login error
const loginError = await $page.$('.alert-danger');

if (loginError) {
  const errorText = await $page.evaluate(
    el => el.textContent.trim(),
    loginError
  );

  throw new Error(`Login failed: ${errorText}`);
}

// Optional: verify login succeeded
const currentUrl = $page.url();

if (currentUrl.includes('/login')) {
  throw new Error('Login may have failed. Still on login page.');
}

// Get cookies
const cookies = await $page.cookies();

return [
  {
    json: {
      success: true,
      currentUrl,
      cookies
    }
  }
];

const {
    cookies,
    keyword,
    startDate,
    endDate
} = $json;

if (cookies && cookies.length) {
    await $page.setCookie(...cookies);
}

await $page.setViewport({
    width: 1512,
    height: 982,
    deviceScaleFactor: 1
});

async function extractTable() {
    return await $page.evaluate(() => {
        const table =
            document.querySelector('table.dataTable') ||
            document.querySelector('table');
        if (!table) return [];
        const headers = Array.from(
            table.querySelectorAll('thead th')
        ).map(th => th.innerText.trim());
        return Array.from(table.querySelectorAll('tbody tr'))
            .map(tr => {
                const cells = Array.from(tr.querySelectorAll('td'));
                if (!cells.length) return null;

                const row = Object.fromEntries(
                    headers.map((h, i) => [
                        h || `col_${i}`,
                        (cells[i]?.innerText ?? '').trim()
                    ])
                );

                // grab the id from any element in the row that carries data-id
                const el = tr.querySelector('[data-id]');
                let id = el ? el.getAttribute('data-id') : null;

                // fallback: parse it out of a purchase/<action>/<id> href
                if (!id) {
                    const link = tr.querySelector('a[href*="purchase/"]');
                    const m = link && link.getAttribute('href').match(/purchase\/\w+\/(\d+)/);
                    id = m ? m[1] : null;
                }

                row.id = id;
                return row;
            })
            .filter(Boolean);
    });
}

async function isNextDisabled() {
    return await $page.evaluate(() => {
        const nextLi = document.querySelector('li.next');

        return !nextLi || nextLi.classList.contains('disabled');
    });
}


await $page.goto(
    'https://meta-digitrading.lhike-erp.com/purchase', {
        waitUntil: 'networkidle2',
        timeout: 60000
    }
);

const landedUrl = $page.url();

if (!/\/purchase/i.test(landedUrl)) {
    throw new Error(
        `Expected /purchase but landed on: ${landedUrl} — cookies/session may be invalid.`
    );
}

await $page.waitForSelector('input#sissuedate', {
    timeout: 60000
});

await $page.waitForSelector('input#eissuedate', {
    timeout: 60000
});

await $page.$eval('input#sissuedate', el => (el.value = ''));
await $page.$eval('input#eissuedate', el => (el.value = ''));
await $page.$eval('input#sitem', el => (el.value = ''));

await $page.type('input#sissuedate', startDate, {
    delay: 50
});
await $page.type('input#eissuedate', endDate, {
    delay: 50
});

await $page.type('input#sitem', keyword, {
    delay: 50
});

await $page.click('a#btndtsearch');

await $page.waitForNetworkIdle({
    idleTime: 500,
    timeout: 30000
});

try {
    await $page.select('select[name$="_length"]', '100');

    await $page.waitForNetworkIdle({
        idleTime: 500,
        timeout: 30000
    });
} catch (_) {}

await $page.waitForSelector('table');

const all = [];
const seen = new Set();

while (true) {
    const pageRows = await extractTable();

    for (const r of pageRows) {
        const key = JSON.stringify(r);

        if (!seen.has(key)) {
            seen.add(key);
            all.push(r);
        }
    }

    if (await isNextDisabled()) {
        break;
    }

    const firstRowSig = await $page.evaluate(() => {
        const first =
            document.querySelector(
                'table.dataTable tbody tr, table tbody tr'
            );

        return first ? first.innerText.trim() : '';
    });

    await $page.click('li.next a');

    await $page.waitForFunction(
        prev => {
            const first =
                document.querySelector(
                    'table.dataTable tbody tr, table tbody tr'
                );

            const now = first ? first.innerText.trim() : '';

            return now && now !== prev;
        }, {
            timeout: 30000
        },
        firstRowSig
    );
}

return [{
    json: {
        startDate,
        endDate,
        keyword,
        totalRows: all.length,
        rows: all
    },
}];

