const statusMap = {
  "For Approval": 1,
  "Approved": 2,
  "To Pay": 3,
  "Paid": 4,
  "For Purchase": 5,
  "Waiting For Delivery": 6,
  "Delivered": 7,
  "Cancelled": 8
};

const output = [];
for (const item of items) {
  const rows = (item.json.rows || [])
      .filter(item => {
        return item["No"] != "No data available in table";
      })
  for (const row of rows) {
    const cleanRow = {};
    for (const [key, value] of Object.entries(row)) {
      cleanRow[key.replace(/\u00A0/g, ' ').trim()] = value;
    }

    // take only the part before " - ", then trim
    const rawStatus = cleanRow["Status"] || "";
    const statusName = rawStatus.split(" - ")[0].trim();

    output.push({
      json: {
        id: cleanRow['id'],
        inventory_item_id: $('Code in JavaScript4').first().json.id,
        issueDate: cleanRow["Issue Date"],
        deliveryNo: cleanRow["Delivery No."],
        customerPoNo: cleanRow["Cust. PO No."],
        controlNo: cleanRow["Control No."],
        item: cleanRow["Item"],
        cogAmount: Number(String(cleanRow["COG Amount"] || 0).replace(/,/g, "")),
        deliveryFee: Number(String(cleanRow["Delivery Fee"] || 0).replace(/,/g, "")),
        totalAmount: Number(String(cleanRow["Total Amount"] || 0).replace(/,/g, "")),
        statusName: statusName,
        statusId: statusMap[statusName] || null,
        pickupDate: cleanRow["Pickup Date"] === "0000-00-00" ? null : cleanRow["Pickup Date"],
        supplier: cleanRow["Supplier"]
      }
    });
  }
}

return output.filter(o => o.json.item.toLowerCase() === $input.first().json.keyword.toLowerCase());

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.cookies = $('Login').first().json.cookies;
  item.json.keyword = $input.first().json.keyword;
  item.json.startDate = $('Webhook').first().json.body.start_date;
  item.json.endDate = $('Webhook').first().json.body.end_date;
}

return $input.all();

