const { cookies, id, poId, statusId, inventory_item_id,  } = $json;
const targetId = id ?? poId;
if (!targetId) {
  throw new Error('No PO id provided (expected $json.id or $json.poId).');
}

if (cookies && cookies.length) {
  await $page.setCookie(...cookies);
}
await $page.setViewport({ width: 1512, height: 982, deviceScaleFactor: 1 });

const url = `https://meta-digitrading.lhike-erp.com/purchase/view/${targetId}`;
await $page.goto(url, { waitUntil: 'networkidle2', timeout: 60000 });

const landedUrl = $page.url();
if (!/\/purchase\/view\//i.test(landedUrl)) {
  throw new Error(`Expected /purchase/view but landed on: ${landedUrl} — cookies/session may be invalid.`);
}

await $page.waitForSelector('#purchaseForm', { timeout: 60000 });

const data = await $page.evaluate(() => {
  // --- helpers ---
  const clean = s => (s == null ? null : String(s).replace(/\u00A0/g, ' ').trim());
  const txt  = el => (el ? clean(el.innerText) : null);      // visible text
  const ctxt = el => (el ? clean(el.textContent) : null);    // text even if hidden
  const val  = sel => {
    const el = document.querySelector(sel);
    return el ? clean(el.value) : null;
  };
  const num = v => {
    if (v == null) return null;
    const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
    return Number.isNaN(n) ? null : n;
  };
  const cleanDate = v => (v === '0000-00-00' ? null : v);
  const selText = sel => {
    const el = document.querySelector(sel);
    if (!el || el.selectedIndex < 0) return null;
    const opt = el.options[el.selectedIndex];
    return opt ? clean(opt.text) : null;
  };
  const selectedMulti = sel => {
    const el = document.querySelector(sel);
    if (!el) return [];
    return Array.from(el.selectedOptions).map(o => ({ id: o.value, name: clean(o.text) }));
  };

  // TOTAL AMOUNT and TOTAL BALANCE share name="txttotalAmt"
  const totals = Array.from(document.querySelectorAll('input[name="txttotalAmt"]'));
  const totalAmountStr  = totals[0] ? totals[0].value : null;
  const totalBalanceStr = totals[1] ? totals[1].value : null;

  // current status: dropdown toggle is .hidden (innerText would be empty -> use textContent)
  const currentStatus =
    ctxt(document.querySelector('.btn-group .dropdown-toggle small b')) ||
    txt(document.querySelector('.note-success h4'));

  // order items table
  const items = Array.from(document.querySelectorAll('#divselorder table tr.new-tr')).map(tr => {
    const tds = Array.from(tr.querySelectorAll('td'));
    return {
      qty:    num(txt(tds[0])),
      item:   txt(tds[1]),
      cog:    num(txt(tds[2])),
      amount: num(txt(tds[3])),
      goods:  num(txt(tds[4])),
      damage: num(txt(tds[5])),
    };
  });

  // receipts
  const receipts = Array.from(document.querySelectorAll('.img-receipt'))
    .map(img => img.getAttribute('src'))
    .filter(Boolean);

  // history panel (right column)
  let createdBy = null, createdDate = null, lastUpdatedBy = null, lastUpdatedDate = null;
  const statusLog = [];
  const historyRaw = [];
  const histTable = document.querySelector('table.table-bordered');
  if (histTable) {
    const rows = Array.from(histTable.querySelectorAll('tr'));
    rows.forEach(r => historyRaw.push(txt(r)));

    for (let i = 0; i < rows.length; i++) {
      const label = txt(rows[i]);
      const next = rows[i + 1] ? txt(rows[i + 1]) : null;
      if (label === 'Created by') createdBy = next;
      else if (label === 'Created Date') createdDate = next;
      else if (label === 'Last updated by') lastUpdatedBy = next;
      else if (label === 'Last updated Date') lastUpdatedDate = next;
    }

    rows.forEach((r, i) => {
      const t = txt(r);
      if (t && t.startsWith('Status:')) {
        const b = r.querySelector('b');
        const small = r.querySelector('small');
        const detailRow = rows[i + 1];
        let detail = null, timestamp = null;
        if (detailRow) {
          detail = txt(detailRow);
          const smalls = detailRow.querySelectorAll('small');
          timestamp = smalls.length ? clean(smalls[smalls.length - 1].textContent) : null;
        }
        statusLog.push({
          status: b ? txt(b) : null,
          by: small ? txt(small) : null,
          detail,
          timestamp,
        });
      }
    });
  }

  return {
    poId:        val('#txtpoid'),
    empId:       val('#txtempid'),
    action:      val('#txtaction'),
    currentStatus,
    issueDate:   cleanDate(val('input[name="txtissuedate"]')),
    customerPoNo: val('input[name="txtcustpo"]'),
    controlNo:   val('input[name="txtctrolno"]'),
    deliveryNo:  val('input[name="txtdeliveryno"]'),
    deliveryTo:  val('input[name="txtdeliveryto"]'),
    deliveryAddress: val('textarea[name="txtdeliveryadd"]'),
    supplier:    selText('#selsupp'),
    supplierId:  (document.querySelector('#selsupp') || {}).value || null,
    deliveryFee: num(val('#txtdeliveryamt')),
    discount:    num(val('#txtdiscount')),
    payment:     num(val('input[name="txttotaldpAmt"]')),
    totalAmount: num(totalAmountStr),
    totalBalance: num(totalBalanceStr),
    assignedTo:  selectedMulti('#assignedto'),
    pickupDate:  cleanDate(val('input[name="txtpickedupdate"]')),
    remarks:     val('textarea[name="txtremarks"]'),
    receipts,
    items,
    history: {
      createdBy,
      createdDate,
      lastUpdatedBy,
      lastUpdatedDate,
      statusLog,
      raw: historyRaw,
    },
  };
});

return [{ json: { ...data, statusId } }];

